import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3, 4]  # positions 1..4

    # Attributes as per puzzle
    Names = ["Peter", "Eric", "Alice", "Arnold"]
    Educations = ["bachelor", "high school", "associate", "master"]
    Musics = ["jazz", "rock", "pop", "classical"]
    Colors = ["green", "red", "yellow", "white"]
    Flowers = ["lilies", "carnations", "daffodils", "roses"]

    solutions = []

    # Helper to get position of a value in an assignment array
    def pos_of(value, arr):
        return arr.index(value)

    for names in permutations(Names):
        # 5. Eric is not in the second house.
        if names[1] == "Eric":
            continue
        # 6. Arnold is not in the third house.
        if names[2] == "Arnold":
            continue

        for edu in permutations(Educations):
            # 3. The person with a master's degree is Alice.
            if pos_of("master", edu) != pos_of("Alice", names):
                continue
            # 9. The person with an associate's degree is not in the fourth house.
            if pos_of("associate", edu) == 3:
                continue
            # 1 and 14 constraints link later with color/flower; check later.

            for music in permutations(Musics):
                # 8. The person who loves pop music is in the second house.
                if music[1] != "pop":
                    continue
                # 4. The person with a master's degree is directly left of the person who loves classical music.
                if pos_of("master", edu) + 1 != pos_of("classical", music):
                    continue

                for color in permutations(Colors):
                    # 13. Arnold is the person who loves yellow.
                    if pos_of("Arnold", names) != pos_of("yellow", color):
                        continue
                    # 11. The person whose favorite color is red is directly left of the person who loves white.
                    if pos_of("red", color) + 1 != pos_of("white", color):
                        continue
                    # 12. The person whose favorite color is red is the person who loves rock music.
                    if pos_of("red", color) != pos_of("rock", music):
                        continue
                    # 1. bachelor's degree = daffodils; 14. daffodils = yellow -> bachelor = yellow
                    if pos_of("bachelor", edu) != pos_of("yellow", color):
                        continue

                    for flower in permutations(Flowers):
                        # 2. The person who loves a carnations arrangement is not in the first house.
                        if pos_of("carnations", flower) == 0:
                            continue
                        # 10. The person who loves a carnations arrangement is not in the fourth house.
                        if pos_of("carnations", flower) == 3:
                            continue
                        # 14. The person who loves a bouquet of daffodils is the person who loves yellow.
                        if pos_of("daffodils", flower) != pos_of("yellow", color):
                            continue
                        # 1. The person with a bachelor's degree is the person who loves a bouquet of daffodils.
                        if pos_of("bachelor", edu) != pos_of("daffodils", flower):
                            continue
                        # 7. The person who loves yellow is directly left of the person who loves the rose bouquet.
                        if pos_of("yellow", color) + 1 != pos_of("roses", flower):
                            continue

                        # All constraints satisfied; record solution
                        solutions.append((names, edu, music, color, flower))

    # Prepare JSON output from the (unique) solution
    if not solutions:
        raise RuntimeError("No solution found")
    # Assuming unique solution
    names, edu, music, color, flower = solutions[0]

    header = ["House", "Name", "level of education", "favorite music genres", "favorite color", "favorite flower"]
    rows = []
    for i in range(4):
        rows.append([
            str(i + 1),
            names[i],
            edu[i],
            music[i],
            color[i],
            flower[i],
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
